public class LongestSubstringWithoutRepeating {

public static int lengthOfLongestSubstring(String s) {
int n = s.length();
int[] arr = new int[26];
int maxLength = 0;
int i = 0;
int j = 0;

while (j  1) {
arr[s.charAt(i) - 'a']--;
i++;
}

maxLength = Math.max(maxLength, j - i + 1);
j++;
}

return maxLength;
}

public static void main(String[] args) {
String input = "ganeshjagginenigani";
